// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        vm.assume(ancillaryData.length <= 256);
        int256 priceBefore = c.getPrice(identifier, time, ancillaryData);
        c.assertionDisputedCallback(keccak256(abi.encode(identifier, time, ancillaryData)));
        int256 priceAfter = c.getPrice(identifier, time, ancillaryData);
        assertTrue(priceBefore == 0 && priceAfter == 0, "getPrice must return 0");
    }
}

